                if code "'!= 0:
                    final='"'failed'; break
                if phase=='health-check':
                    final='passed'; break
        if final: break
    snapshot={'result':final or 'incomplete','started_at_monotonic':0,'elapsed_seconds':round(time.monotonic()-start,3),'statuses':seen,'still_running_phase':next((p for p in phases if p not in seen),None)}
    out.write_text(json.dumps(snapshot,indent=2)+'\\n')
    if final: break
    time.sleep(5)
snapshot={'result':final,'elapsed_seconds':round(time.monotonic()-start,3),'statuses':seen,'still_running_phase':None if final in ('passed','failed','stopped') else next((p for p in phases if p not in seen),None)}
